import {
  isBackbone
} from "./chunk-FYQWPEEY.js";

// src/tubeMap/connectors.ts
function referenceNodes(graph, layout) {
  const nodeById = new Map(graph.nodes.map((n) => [n.id, n]));
  const out = [];
  layout.nodes.forEach((node) => {
    const graphNode = nodeById.get(node.name);
    if (node.order >= 0 && graphNode && isBackbone(graphNode)) {
      out.push({
        node: node.name,
        bp0: graphNode.stable.start,
        bp1: graphNode.stable.start + node.sequenceLength,
        x0: node.x,
        x1: node.x + node.pixelWidth
      });
    }
  });
  return out;
}
function tubeMapConnectors(nodes, bpToScreen, tubeToScreen, width) {
  const out = [];
  for (const n of nodes) {
    const bottom0 = tubeToScreen(n.x0);
    const bottom1 = tubeToScreen(n.x1);
    if (bottom1 >= 0 && bottom0 <= width) {
      out.push({
        node: n.node,
        top0: bpToScreen(n.bp0),
        top1: bpToScreen(n.bp1),
        bottom0,
        bottom1
      });
    }
  }
  return out;
}
var HIT_SLOP_PX = 3;
function connectorAt(connectors, zoneBottom, sx, sy) {
  if (zoneBottom <= 0 || sy < 0 || sy > zoneBottom) {
    return void 0;
  }
  const t = sy / zoneBottom;
  let hit;
  let best = HIT_SLOP_PX;
  for (const c of connectors) {
    const a = c.top0 + (c.bottom0 - c.top0) * t;
    const b = c.top1 + (c.bottom1 - c.top1) * t;
    const dist = Math.max(0, Math.min(a, b) - sx, sx - Math.max(a, b));
    if (dist < best) {
      best = dist;
      hit = c.node;
    }
  }
  return hit;
}
function band(ctx, c, bottom) {
  ctx.moveTo(c.top0, 0);
  ctx.lineTo(c.top1, 0);
  ctx.lineTo(c.bottom1, bottom);
  ctx.lineTo(c.bottom0, bottom);
  ctx.closePath();
}
function sides(ctx, c, bottom) {
  ctx.moveTo(c.top0, 0);
  ctx.lineTo(c.bottom0, bottom);
  ctx.moveTo(c.top1, 0);
  ctx.lineTo(c.bottom1, bottom);
}
function drawTubeMapConnectors(ctx, connectors, bottom, {
  highlightNode,
  darkMode
}) {
  if (bottom <= 0 || connectors.length === 0) {
    return;
  }
  const ink = darkMode ? "255,255,255" : "0,0,0";
  ctx.beginPath();
  for (const c of connectors) {
    band(ctx, c, bottom);
  }
  ctx.fillStyle = `rgba(${ink},0.07)`;
  ctx.fill();
  ctx.beginPath();
  for (const c of connectors) {
    sides(ctx, c, bottom);
  }
  ctx.strokeStyle = `rgba(${ink},0.35)`;
  ctx.lineWidth = 0.5;
  ctx.stroke();
  const lit = connectors.find((c) => c.node === highlightNode);
  if (lit) {
    ctx.beginPath();
    band(ctx, lit, bottom);
    ctx.fillStyle = "rgba(255,192,203,0.5)";
    ctx.fill();
    ctx.beginPath();
    sides(ctx, lit, bottom);
    ctx.strokeStyle = "#ff0000";
    ctx.lineWidth = 1;
    ctx.stroke();
  }
}

export {
  referenceNodes,
  tubeMapConnectors,
  connectorAt,
  drawTubeMapConnectors
};
