import {
  el
} from "./chunk-NNODIW4U.js";

// src/genes/exonOutline.ts
var EXON_COLOR = "#daa520";
var EXON_GAP_PX = 1;
var EXON_LINE_PX = 2;
var MIN_LANE_PX = 4;
function exonStretches(pins, halfWidthPx, lift, pathOf = (d) => d) {
  const inkPx = (nodeId) => {
    const own = halfWidthPx(nodeId) * 2;
    return lift?.nodeIds.has(nodeId) ? Math.max(own, lift.walks.length * MIN_LANE_PX) : own;
  };
  return pins.flatMap(
    (pin) => pin.exonsByNode.map(({ nodeId, d }) => ({
      key: `${pin.gene.name}-${pin.gene.start}-${nodeId}`,
      d: pathOf(d),
      inner: inkPx(nodeId) + 2 * EXON_GAP_PX
    }))
  );
}
function exonOutlineTree(stretches, o) {
  if (stretches.length === 0) {
    return void 0;
  }
  const stroke = (s, color, width) => el("path", {
    d: s.d,
    fill: "none",
    stroke: color,
    "stroke-width": width,
    "stroke-linecap": "round",
    "stroke-linejoin": "round",
    "vector-effect": o.transform ? "non-scaling-stroke" : void 0
  });
  return el(
    "g",
    {},
    el(
      "mask",
      {
        id: o.id,
        maskUnits: "userSpaceOnUse",
        x: 0,
        y: 0,
        width: o.width,
        height: o.height
      },
      el(
        "g",
        { transform: o.transform },
        ...stretches.map((s) => stroke(s, "#fff", s.inner + 2 * EXON_LINE_PX)),
        ...stretches.map((s) => stroke(s, "#000", s.inner))
      )
    ),
    el("rect", {
      width: o.width,
      height: o.height,
      fill: EXON_COLOR,
      mask: `url(#${o.id})`
    })
  );
}

export {
  EXON_COLOR,
  exonStretches,
  exonOutlineTree
};
