// src/renderer/canvas.ts
var MAX_DPR = 2;
var MAX_CANVAS_DIM_PX = 8192;
function getDpr() {
  return typeof devicePixelRatio === "undefined" ? 1 : Math.min(devicePixelRatio, MAX_DPR);
}
var warnedCanvasClamp = false;
function backingPx(cssSize, dpr, axis) {
  const value = Math.round(cssSize * dpr);
  if (value > MAX_CANVAS_DIM_PX) {
    if (!warnedCanvasClamp) {
      warnedCanvasClamp = true;
      console.warn(
        `Canvas ${axis} ${value}px exceeds the safe limit ${MAX_CANVAS_DIM_PX}px and was clamped`
      );
    }
    return MAX_CANVAS_DIM_PX;
  }
  return value;
}
function syncCanvasSize(canvas, width, height) {
  const dpr = getDpr();
  const pw = backingPx(width, dpr, "width");
  const ph = backingPx(height, dpr, "height");
  if (canvas.width !== pw || canvas.height !== ph) {
    canvas.width = pw;
    canvas.height = ph;
  }
  const cssWidth = `${width}px`;
  const cssHeight = `${height}px`;
  if (canvas.style.width !== cssWidth) {
    canvas.style.width = cssWidth;
  }
  if (canvas.style.height !== cssHeight) {
    canvas.style.height = cssHeight;
  }
}

export {
  MAX_DPR,
  MAX_CANVAS_DIM_PX,
  getDpr,
  syncCanvasSize
};
