import {
  tubeSpan
} from "./chunk-DRA7733Q.js";

// src/tubeMap/genes.ts
function tubeMapGenes(byRefName, genes) {
  const out = [];
  for (const gene of genes) {
    const boxes = byRefName.get(gene.refName);
    const first = boxes?.[0];
    const last = boxes?.at(-1);
    if (!boxes || !first || !last) {
      continue;
    }
    const start = Math.max(gene.start, first.bp0);
    const end = Math.min(gene.end, last.bp1);
    if (end <= start) {
      continue;
    }
    out.push({
      gene,
      ...tubeSpan(boxes, start, end),
      exons: gene.exons.filter((e) => e.end > start && e.start < end).map(
        (e) => tubeSpan(boxes, Math.max(e.start, start), Math.min(e.end, end))
      )
    });
  }
  return out;
}
var GENE_ROW_PX = 22;
var MAX_GENE_ROWS = 4;
var EXON_PX = 8;
var NAME_FONT = "11px sans-serif";
var NAME_GAP_PX = 8;
function tubeMapGeneRows(genes) {
  const edges = genes.flatMap((g) => [
    { x: g.x0, step: 1 },
    { x: g.x1, step: -1 }
  ]).sort((a, b) => a.x - b.x || a.step - b.step);
  let depth = 0;
  let most = 0;
  for (const { step } of edges) {
    depth += step;
    most = Math.max(most, depth);
  }
  return Math.min(MAX_GENE_ROWS, most);
}
function drawTubeMapGenes(ctx, genes, frame, bottom, top = 0) {
  const { x, width, darkMode } = frame;
  const rows = Math.max(1, Math.floor((bottom - top) / GENE_ROW_PX));
  const rowEnds = [];
  const ink = darkMode ? "#e0e0e6" : "#1c1c22";
  ctx.font = NAME_FONT;
  ctx.textAlign = "center";
  ctx.textBaseline = "alphabetic";
  ctx.fillStyle = ink;
  ctx.strokeStyle = ink;
  ctx.lineWidth = 1;
  const placed = genes.map((g) => ({ g, s0: x(g.x0), s1: x(g.x1) })).filter(({ s0, s1 }) => s1 >= 0 && s0 <= width).sort((a, b) => a.s0 - b.s0);
  for (const { g, s0, s1 } of placed) {
    const arrow = g.gene.strand > 0 ? " \u2192" : g.gene.strand < 0 ? "\u2190 " : "";
    const label = g.gene.strand < 0 ? `${arrow}${g.gene.name}` : `${g.gene.name}${arrow}`;
    const mid = (Math.max(s0, 0) + Math.min(s1, width)) / 2;
    const half = ctx.measureText(label).width / 2;
    const left = Math.min(s0, mid - half);
    const right = Math.max(s1, mid + half);
    let row = rowEnds.findIndex((end) => end + NAME_GAP_PX <= left);
    if (row === -1) {
      row = Math.min(rowEnds.length, rows - 1);
    }
    rowEnds[row] = Math.max(rowEnds[row] ?? -Infinity, right);
    const glyphY = bottom - row * GENE_ROW_PX - EXON_PX / 2;
    ctx.beginPath();
    ctx.moveTo(s0, glyphY + 0.5);
    ctx.lineTo(s1, glyphY + 0.5);
    ctx.stroke();
    for (const e of g.exons) {
      const e0 = x(e.x0);
      ctx.fillRect(e0, glyphY - EXON_PX / 2, Math.max(1, x(e.x1) - e0), EXON_PX);
    }
    ctx.fillText(label, mid, glyphY - EXON_PX / 2 - 2);
  }
}

export {
  tubeMapGenes,
  GENE_ROW_PX,
  tubeMapGeneRows,
  drawTubeMapGenes
};
